// Temporal Force-Directed Graph — Network, route: ref
// Source: temporal-force-directed-graph
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useEffect, useMemo, useRef } from 'react';
import * as d3 from 'd3';

// ---- inlined from forceGraph ----
type GraphNode = { id: string; group: string };
type GraphLink = { source: string; target: string; value: number };

const GROUP_NAMES = ['Runtime', 'Scales', 'Shapes', 'Layouts', 'Interaction', 'Color'];

/** Six communities of nine modules each; the first of every list is its hub. */
const MEMBERS: string[][] = [
  ['selection', 'transition', 'timer', 'dispatch', 'ease', 'interpolate', 'format', 'time-format', 'dsv'],
  ['scale-linear', 'scale-log', 'scale-pow', 'scale-time', 'scale-band', 'scale-point', 'scale-ordinal', 'scale-quantile', 'scale-sequential'],
  ['arc', 'line', 'area', 'pie', 'stack', 'symbol', 'curve', 'link-shape', 'radial-line'],
  ['force', 'hierarchy', 'tree', 'cluster', 'treemap', 'pack', 'partition', 'chord', 'sankey'],
  ['zoom', 'drag', 'brush', 'quadtree', 'polygon', 'contour', 'delaunay', 'voronoi', 'hexbin'],
  ['color', 'rgb', 'hsl', 'lab', 'hcl', 'scheme', 'interpolate-rgb', 'interpolate-hcl', 'legend']
];

/** Mulberry32. The graph must be byte-identical on every load, so never Math.random. */
function seeded(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const graphNodes: GraphNode[] = GROUP_NAMES.flatMap((group, g) =>
  MEMBERS[g].map((id) => ({ id, group }))
);

function buildLinks(): GraphLink[] {
  const random = seeded(20260813);
  const seen = new Set<string>();
  const links: GraphLink[] = [];

  const add = (source: string, target: string, value: number) => {
    const key = source < target ? `${source}|${target}` : `${target}|${source}`;
    if (source === target || seen.has(key)) return;
    seen.add(key);
    links.push({ source, target, value });
  };

  MEMBERS.forEach((members) => {
    const [hub, ...rest] = members;
    rest.forEach((id) => add(hub, id, 1 + Math.floor(random() * 4)));
    // Chords inside the community so it reads as a cluster rather than a star.
    for (let k = 0; k < 7; k++) {
      add(rest[Math.floor(random() * rest.length)], rest[Math.floor(random() * rest.length)], 1);
    }
  });

  // Hub-to-hub ring plus peripheral bridges: enough coupling to pull the communities
  // together without dissolving them.
  MEMBERS.forEach((members, g) => add(members[0], MEMBERS[(g + 1) % MEMBERS.length][0], 4));
  for (let k = 0; k < 12; k++) {
    const a = MEMBERS[Math.floor(random() * MEMBERS.length)];
    const b = MEMBERS[Math.floor(random() * MEMBERS.length)];
    add(a[1 + Math.floor(random() * 8)], b[1 + Math.floor(random() * 8)], 1);
  }

  return links;
}

const graphLinks: GraphLink[] = buildLinks();

// ---- inlined from temporalGraph ----
type TemporalNode = { id: string; group: string; start: number; end: number };
type TemporalLink = { source: string; target: string; start: number; end: number };

const TOPICS = ['Genomics', 'Systems', 'Networks', 'Imaging', 'Ecology'];

/** Two 8-hour programme days laid end to end; minute 0 is 09:00 on day one. */
const DAY = 480;
const TOTAL = DAY * 2;
const FRAME_STEP = 8;
const ATTENDEES = 60;

const isActive = ({ start, end }: { start: number; end: number }, time: number): boolean =>
  start <= time && time < end;

function formatClock(time: number): string {
  const day = time < DAY ? 1 : 2;
  const minutes = 9 * 60 + (time % DAY);
  return `Day ${day}, ${Math.floor(minutes / 60)}:${String(minutes % 60).padStart(2, '0')}`;
}

function buildNodes(): TemporalNode[] {
  const random = seeded(20260814);
  return Array.from({ length: ATTENDEES }, (_, i) => {
    const roll = random();
    const group = TOPICS[i % TOPICS.length];
    const id = `P${String(i + 1).padStart(2, '0')}`;
    if (roll < 0.3) return { id, group, start: Math.round(random() * 90), end: 360 + Math.round(random() * 120) };
    if (roll < 0.6) return { id, group, start: DAY + Math.round(random() * 80), end: 840 + Math.round(random() * 120) };
    return { id, group, start: Math.round(random() * 60), end: 900 + Math.round(random() * 60) };
  });
}

const temporalNodes: TemporalNode[] = buildNodes();

/**
 * Contacts open in 20-minute windows among whoever is present, mostly within a topic.
 * Every contact is clipped to both endpoints' presence so no link ever outlives its nodes.
 */
function buildLinks_temporalGraph(): TemporalLink[] {
  const random = seeded(31415926);
  const links: TemporalLink[] = [];

  for (let window = 0; window < TOTAL; window += 20) {
    const present = temporalNodes.filter((d) => d.start <= window && window + 30 < d.end);
    for (let k = 0; k < Math.round(present.length * 0.5); k++) {
      const a = present[Math.floor(random() * present.length)];
      const pool = random() < 0.7 ? present.filter((d) => d.group === a.group) : present;
      const b = pool[Math.floor(random() * pool.length)];
      if (!b || b.id === a.id) continue;
      const start = window + Math.floor(random() * 15);
      const end = Math.min(start + 25 + Math.floor(random() * 55), a.end, b.end);
      if (end - start >= 12) links.push({ source: a.id, target: b.id, start, end });
    }
  }

  return links;
}

const temporalLinks: TemporalLink[] = buildLinks_temporalGraph();

/** Frames with no contacts at all are dropped so the loop never opens on scattered dots. */
const frames: number[] = Array.from(
  { length: TOTAL / FRAME_STEP },
  (_, i) => i * FRAME_STEP
).filter((time) => temporalLinks.filter((d) => isActive(d, time)).length >= 6);

type SimNode = d3.SimulationNodeDatum & { id: string; group: string };
type SimLink = d3.SimulationLinkDatum<SimNode> & { start: number };

const FORCE_SEED = 20260813;
const FRAME_MS = 240;
const RADIUS = 5;
/** Bands reserved for the legend and clock above, and the provenance caption below. */
const TOP_BAND = 30;
const BOTTOM_BAND = 20;

const endpointId = (end: SimLink['source']): string =>
  typeof end === 'object' ? end.id : String(end);

/**
 * Nodes and links that each carry the window `[start, end)` they exist over, the times
 * the animation samples, and the topic names `group` draws from.
 */
export type Data = {
  nodes: { id: string; group: string; start: number; end: number }[];
  links: { source: string; target: string; start: number; end: number }[];
  frames: number[];
  topics: string[];
};

const DEMO: Data = { nodes: temporalNodes, links: temporalLinks, frames, topics: TOPICS };

export default function TemporalForceDirectedGraph({ data = DEMO, width }:
  { data?: Data; width: number }) {
  const ref = useRef<SVGSVGElement | null>(null);
  const height = Math.round(width * 0.62);
  const showLegend = width >= 640;

  const color = useMemo(
    () => d3.scaleOrdinal<string, string>(data.topics, d3.schemeObservable10),
    [data]
  );

  useEffect(() => {
    const element = ref.current;
    if (!element || width === 0) return;

    const svg = d3.select(element);
    svg.selectAll('*').remove(); // StrictMode runs this effect twice in development.

    const simulation = d3
      .forceSimulation<SimNode, SimLink>()
      .randomSource(seeded(FORCE_SEED))
      .force('charge', d3.forceManyBody<SimNode>().strength(-75).distanceMax(280))
      .force(
        'link',
        d3
          .forceLink<SimNode, SimLink>()
          .id((d) => d.id)
          .distance(28)
          .strength(0.5)
      )
      .force('x', d3.forceX<SimNode>().strength(0.06))
      .force('y', d3.forceY<SimNode>().strength(0.09))
      .force('collide', d3.forceCollide<SimNode>(RADIUS + 2))
      .on('tick', ticked);

    let link = svg
      .append('g')
      .attr('stroke', 'var(--muted)')
      .attr('stroke-opacity', 0.45)
      .selectAll<SVGLineElement, SimLink>('line');

    let node = svg
      .append('g')
      .attr('stroke', 'var(--bg)')
      .attr('stroke-width', 1.5)
      .selectAll<SVGCircleElement, SimNode>('circle');

    const clock = svg
      .append('text')
      .attr('x', width / 2 - 8)
      .attr('y', -height / 2 + 18)
      .attr('text-anchor', 'end')
      .attr('font-size', 13)
      .attr('font-variant-numeric', 'tabular-nums')
      .attr('fill', 'var(--text)');

    svg
      .append('text')
      .attr('x', -width / 2 + 8)
      .attr('y', height / 2 - 6)
      .attr('font-size', 10)
      .attr('fill', 'var(--muted)')
      .text(
        width >= 520
          ? 'Synthetic seeded contact log, not the SocioPatterns SFHH conference data.'
          : 'Synthetic seeded data, not SocioPatterns SFHH.'
      );

    if (showLegend) {
      const slot = Math.min(110, (width - 200) / data.topics.length);
      svg
        .append('g')
        .attr('font-size', 11)
        .attr('fill', 'var(--muted)')
        .selectAll('g')
        .data(data.topics)
        .join('g')
        .attr('transform', (_, i) => `translate(${-width / 2 + 8 + i * slot},${-height / 2 + 14})`)
        .call((g) => g.append('circle').attr('r', 4).attr('fill', (d) => color(d)))
        .call((g) => g.append('text').attr('x', 10).attr('dy', '0.32em').text((d) => d));
    }

    function ticked() {
      const limitX = width / 2 - RADIUS - 1;
      const top = -height / 2 + TOP_BAND;
      const bottom = height / 2 - BOTTOM_BAND;
      node
        .attr('cx', (d) => (d.x = Math.max(-limitX, Math.min(limitX, d.x ?? 0))))
        .attr('cy', (d) => (d.y = Math.max(top, Math.min(bottom, d.y ?? 0))));
      link
        .attr('x1', (d) => (d.source as SimNode).x ?? 0)
        .attr('y1', (d) => (d.source as SimNode).y ?? 0)
        .attr('x2', (d) => (d.target as SimNode).x ?? 0)
        .attr('y2', (d) => (d.target as SimNode).y ?? 0);
    }

    const drag = d3
      .drag<SVGCircleElement, SimNode>()
      .on('start', (event, d) => {
        if (!event.active) simulation.alphaTarget(0.3).restart();
        d.fx = d.x;
        d.fy = d.y;
      })
      .on('drag', (event, d) => {
        d.fx = event.x;
        d.fy = event.y;
      })
      .on('end', (event, d) => {
        if (!event.active) simulation.alphaTarget(0);
        d.fx = null;
        d.fy = null;
      });

    // Recycle the previous frame's data objects so a node that persists keeps its position.
    const step = (time: number) => {
      const previous = new Map(node.data().map((d) => [d.id, d]));
      const nodes: SimNode[] = data.nodes
        .filter((d) => isActive(d, time))
        .map((d) => ({ ...previous.get(d.id), ...d }));
      const links: SimLink[] = data.links.filter((d) => isActive(d, time)).map((d) => ({ ...d }));

      node = node.data(nodes, (d) => d.id).join((enter) =>
        enter
          .append('circle')
          .attr('r', RADIUS)
          .attr('fill', (d) => color(d.group))
          .attr('cx', (d) => d.x ?? 0)
          .attr('cy', (d) => d.y ?? 0)
          .style('cursor', 'grab')
          .call(drag)
          .call((c) => c.append('title').text((d) => `${d.id} — ${d.group}`))
      );

      link = link
        .data(links, (d) => `${endpointId(d.source)}|${endpointId(d.target)}|${d.start}`)
        .join('line');

      simulation.nodes(nodes);
      simulation.force<d3.ForceLink<SimNode, SimLink>>('link')?.links(links);
      simulation.alpha(0.9).restart().tick();
      clock.text(formatClock(time));
      ticked();
    };

    let frame = 0;
    step(data.frames[0]);
    const timer = window.setInterval(() => {
      frame = (frame + 1) % data.frames.length;
      step(data.frames[frame]);
    }, FRAME_MS);

    return () => {
      window.clearInterval(timer);
      simulation.on('tick', null).stop();
      node.on('.drag', null);
      svg.selectAll('*').remove();
    };
  }, [data, width, height, showLegend, color]);

  if (width === 0) return null;

  return (
    <svg
      ref={ref}
      viewBox={`${-width / 2} ${-height / 2} ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Temporal force-directed graph of face-to-face contacts at a two-day conference, where nodes and links enter and leave as simulated time advances. Synthetic data from a seeded generator, not the SocioPatterns SFHH dataset."
    />
  );
}
